import io
import random
from werkzeug.sansio.multipart import MultipartDecoder, Data, Field, File, Epilogue, NeedData
from werkzeug.formparser import MultiPartParser, FormDataParser, parse_form_data
from werkzeug.wrappers import Request
from werkzeug.exceptions import RequestEntityTooLarge

boundary = b'a.b+$[]()?'
payloads = [b'', b'\r', b'\n', b'\r\n', b'\0abc\xff\n\r', b'\0' * 65535 + b'\r']
payloads += [b'before\r\n--' + boundary + suffix + b'\r\nafter' for suffix in [b'--X', b'--!', b'---', b'----', b' \tX', b'-- \tX']]

def message(payloads, nl=b'\r\n', end=True):
    body = b'preamble'+nl
    for i, p in enumerate(payloads):
        body += b'--'+boundary+b' \t'+nl+b'Content-Disposition: form-data; name="same"'
        if i % 2:
            body += b'; filename="a.bin"'
        body += nl+b'X-Test: value'+nl+nl+p+nl
    return body+b'--'+boundary+b'-- \t'+(nl+b'epilogue' if end else b'')

def decode(chunks):
    d = MultipartDecoder(boundary)
    parts = []
    ends = 0
    for chunk in [*chunks, None]:
        d.receive_data(chunk)
        while True:
            e = d.next_event()
            if isinstance(e, NeedData): break
            if isinstance(e, (File, Field)): parts.append(bytearray())
            if isinstance(e, Data):
                parts[-1] += e.data
                ends += not e.more_data
            if isinstance(e, Epilogue):
                assert ends == len(parts)
                return list(map(bytes, parts))
    raise AssertionError('no epilogue')

checks = 0
for nl in [b'\r\n', b'\r', b'\n']:
    for ending in [True, False]:
        for payload in payloads:
            expected = [payload, b'', b'file\r', b'']
            raw = message(expected, nl, ending)
            splits = range(len(raw)+1) if len(raw)<1000 else [0, 1, 65535, 65536, len(raw)-1, len(raw)]
            for split in splits:
                assert decode([raw[:split], raw[split:]]) == expected, (nl, ending, payload[:50], split)
                checks += 1
            assert decode([raw[i:i+1] for i in range(len(raw))]) == expected
            rng = random.Random(42)
            chunks=[]
            i=0
            while i<len(raw):
                j=i+rng.randint(1, 31)
                chunks.append(raw[i:j]); i=j
            assert decode(chunks) == expected
print('fragmentation cases:', checks)

class Reader(io.BytesIO):
    def read(self, n=-1): return super().read(min(n, 1))
class Sink(io.BytesIO):
    def __init__(self, result='short', close_error=None):
        super().__init__(); self.calls=0; self.result=result; self.close_error=close_error
    def write(self, data):
        if self.result == 'short': return super().write(data[:2])
        return self.result
    def close(self):
        self.calls+=1
        super().close()
        if self.close_error: raise self.close_error
raw=message([b'ab', b'1234', b'', b''])
owned=[]
def factory(**kwargs):
    s=Sink(); owned.append(s); return s
p=MultiPartParser(stream_factory=factory, max_file_size=4, max_form_data_size=6)
for stream in [io.BytesIO(raw), Reader(raw)]:
    form, files=p.parse(stream,boundary,len(raw))
    assert form.getlist('same')==['ab','']
    assert [s.read() for s in files.getlist('same')]==[b'1234',b'']
    assert not any(s.closed for s in owned)
for limit in ['max_file_size', 'max_form_data_size']:
    for size in [0,1,3]:
        owned.clear()
        parser=MultiPartParser(stream_factory=factory, **{limit:size})
        try: parser.parse(Reader(raw),boundary,len(raw))
        except RequestEntityTooLarge: pass
        else: raise AssertionError('quota')
        assert all(s.closed and s.calls==1 for s in owned)
        # Reuse must start counters fresh.
        empty=message([b'',b''])
        parser.parse(Reader(empty),boundary,len(empty))
for invalid in [True,False,-1,0.0,'1',object()]:
    for key in ['max_file_size','max_form_data_size']:
        for cls in [MultiPartParser, FormDataParser]:
            try: cls(**{key:invalid})
            except ValueError: pass
            else: raise AssertionError('validation')
        req=Request.from_values()
        setattr(req,key,invalid)
        try: req.make_form_data_parser()
